import{_ as i,o as l,c as t,a2 as e}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Версия Документов и Пояснения по Обслуживанию","description":"","frontmatter":{},"headers":[],"relativePath":"ru/99-文档版本与维护说明.md","filePath":"ru/99-文档版本与维护说明.md","lastUpdated":1789183869000}'),r={name:"ru/99-文档版本与维护说明.md"};function o(h,a,d,n,s,u){return l(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="версия-документов-и-пояснения-по-обслуживанию" tabindex="-1">Версия Документов и Пояснения по Обслуживанию <a class="header-anchor" href="#версия-документов-и-пояснения-по-обслуживанию" aria-label="Permalink to &quot;Версия Документов и Пояснения по Обслуживанию&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>Номер документа</td><td>99</td></tr><tr><td>Модуль</td><td>Приложения и справочные материалы</td></tr><tr><td>Ключевые слова</td><td>управление версиями, пояснения по обслуживанию, нормы документов, журнал обновлений, обслуживание сеттинга</td></tr></tbody></table><h2 id="i-обзор-системы-документов" tabindex="-1">I. Обзор системы документов <a class="header-anchor" href="#i-обзор-системы-документов" aria-label="Permalink to &quot;I. Обзор системы документов&quot;">​</a></h2><p>Система сеттинга Симбиотической Цивилизации Якоря состоит из 100 документов Markdown, пронумерованных от 00 до 99, разделённых на десять больших модулей, по 10 документов в каждом. Система документов принимает SPEC.md (Спецификация создания документов) как жёсткое ограничение, принимает «00-Хэн Юаньчжоу: Обзор Вселенной» как генеральную канву, подробно развивает документы каждого модуля с разных измерений и, наконец, использует приложения 90-99 для индексации, обобщения и упорядочения. Вся система документов образует полную базу знаний сеттинга, логически самосогласованную, чётко структурированную и взаимно ссылающуюся.</p><p>Проектирование системы документов следует трём главным принципам: «модульность, структурированность, расширяемость». Модульность означает, что каждый документ сосредоточен на одной конкретной теме и является самостоятельным текстом; структурированность означает, что все документы следуют единой спецификации формата, облегчая чтение и поиск; расширяемость означает, что система документов оставляет достаточное пространство для расширения, позволяя постоянно совершенствовать сеттинг путём пересмотра существующих документов и добавления нового содержания.</p><h2 id="ii-правила-нумерации-версии" tabindex="-1">II. Правила нумерации версий <a class="header-anchor" href="#ii-правила-нумерации-версии" aria-label="Permalink to &quot;II. Правила нумерации версий&quot;">​</a></h2><p>Система документов принимает трёхуровневую нумерацию версий «главная версия.второстепенная версия.номер ревизии» :</p><table tabindex="0"><thead><tr><th>Уровень версии</th><th>Правило нумерации</th><th>Условие запуска</th><th>Пример</th></tr></thead><tbody><tr><td>Главная версия</td><td>Возрастает с 1</td><td>Крупная архитектурная перестройка системы документов, например, переразбиение модулей или изменение основных настроек</td><td>v1.0 → v2.0</td></tr><tr><td>Второстепенная версия</td><td>Возрастает с 0</td><td>Содержательная переработка основного содержания какого-либо документа или добавление важного нового содержания сеттинга</td><td>v1.0 → v1.1</td></tr><tr><td>Номер ревизии</td><td>Возрастает с 0</td><td>Несущественные изменения: текстовые правки, корректировка формата, унификация терминологии и т. п.</td><td>v1.0 → v1.0.1</td></tr></tbody></table><p>Текущая общая версия системы документов — v1.0, т. е. первая полная публикация. Каждый документ фиксирует свой номер версии в информационном блоке документа, а общий номер версии системы документов единообразно фиксируется в настоящем документе.</p><h2 id="iii-обзор-спецификации-формата-документов" tabindex="-1">III. Обзор спецификаций формата документов <a class="header-anchor" href="#iii-обзор-спецификации-формата-документов" aria-label="Permalink to &quot;III. Обзор спецификаций формата документов&quot;">​</a></h2><p>Все документы должны следовать следующим единым спецификациям формата (подробные спецификации см. в SPEC.md) :</p><h3 id="_3-1-именование-фаилов" tabindex="-1">3.1 Именование файлов <a class="header-anchor" href="#_3-1-именование-фаилов" aria-label="Permalink to &quot;3.1 Именование файлов&quot;">​</a></h3><p>Формат имени файла — <code>XX-Название документа.md</code>, где XX — двузначный номер от 00 до 99, а название — на китайском языке без пробелов.</p><h3 id="_3-2-структура-документа" tabindex="-1">3.2 Структура документа <a class="header-anchor" href="#_3-2-структура-документа" aria-label="Permalink to &quot;3.2 Структура документа&quot;">​</a></h3><p>Каждый документ должен содержать следующие структурные элементы :</p><ol><li><strong>Заголовок первого уровня</strong> : название документа (соответствует имени файла)</li><li><strong>Информационный блок документа</strong> : таблица номера, модуля и ключевых слов (3-5)</li><li><strong>Основной текст</strong> : не менее 3 разделов с заголовками второго уровня, с использованием структурированных элементов, таких как списки и таблицы</li><li><strong>Заключение</strong> : краткий обобщающий абзац</li><li><strong>Связанные документы</strong> : перечень 2-3 номеров и названий связанных документов</li></ol><h3 id="_3-3-требование-к-объему" tabindex="-1">3.3 Требование к объёму <a class="header-anchor" href="#_3-3-требование-к-объему" aria-label="Permalink to &quot;3.3 Требование к объёму&quot;">​</a></h3><p>Основной текст каждого документа — не менее 800 знаков (без учёта заголовков и метаинформации).</p><h3 id="_3-4-стиль-написания" tabindex="-1">3.4 Стиль написания <a class="header-anchor" href="#_3-4-стиль-написания" aria-label="Permalink to &quot;3.4 Стиль написания&quot;">​</a></h3><ul><li>Серьёзный, систематизированный стиль документа сеттинга, аналогичный энциклопедии/сборнику сеттинга</li><li>Использование единых терминов: «Вселенная Хэнъюань», «Якорь», «Симбиоз» и др.</li><li>Добавляемые новые настройки должны быть логически самосогласованными с существующим сеттингом и соответствовать принципу «Реальность как основа, улучшение через законы»</li></ul><h2 id="iv-организация-обслуживания-и-обязанности" tabindex="-1">IV. Организация обслуживания и обязанности <a class="header-anchor" href="#iv-организация-обслуживания-и-обязанности" aria-label="Permalink to &quot;IV. Организация обслуживания и обязанности&quot;">​</a></h2><h3 id="_4-1-комитет-по-обслуживанию-сеттинга" tabindex="-1">4.1 Комитет по Обслуживанию Сеттинга <a class="header-anchor" href="#_4-1-комитет-по-обслуживанию-сеттинга" aria-label="Permalink to &quot;4.1 Комитет по Обслуживанию Сеттинга&quot;">​</a></h3><p>Комитет по Обслуживанию Сеттинга — высший орган обслуживания системы документов, состоящий из опытных создателей сеттинга, экспертов по логической проверке и представителей пользователей. Его ключевые обязанности включают :</p><ul><li>Утверждение общей архитектуры системы документов и крупных планов пересмотра</li><li>Проверку крупных изменений сеттинга на соответствие основным настройкам</li><li>Разрешение споров по сеттингу и предоставление авторитетных разъяснений</li><li>Регулярную организацию всесторонней самопроверки согласованности сеттинга</li><li>Публикацию общих обновлений версий системы документов</li></ul><h3 id="_4-2-модульные-кураторы" tabindex="-1">4.2 Модульные кураторы <a class="header-anchor" href="#_4-2-модульные-кураторы" aria-label="Permalink to &quot;4.2 Модульные кураторы&quot;">​</a></h3><p>Каждый модуль назначает одного модульного куратора, отвечающего за повседневное обслуживание 10 документов этого модуля. Его обязанности включают :</p><ul><li>Отслеживание согласованности сеттинга документов модуля</li><li>Рассмотрение заявок на пересмотр документов модуля</li><li>Координацию перекрёстных ссылок между документами модуля</li><li>Сбор отзывов и предложений пользователей по содержанию модуля</li><li>Регулярный отчёт о состоянии обслуживания модуля Комитету по Обслуживанию Сеттинга</li></ul><h3 id="_4-3-создатели-документов" tabindex="-1">4.3 Создатели документов <a class="header-anchor" href="#_4-3-создатели-документов" aria-label="Permalink to &quot;4.3 Создатели документов&quot;">​</a></h3><p>Любой соответствующий квалификации создатель может участвовать в создании и пересмотре документов. Обязанности создателей включают :</p><ul><li>Создание или пересмотр документов в соответствии со спецификациями формата</li><li>Обеспечение прохождения созданного содержания проверки по Списку Самопроверки Противоречий Сеттинга</li><li>Приложение подробного описания пересмотра при подаче заявки</li><li>Сотрудничество с работой по проверке кураторов и Комитета</li></ul><h2 id="v-процесс-пересмотра" tabindex="-1">V. Процесс пересмотра <a class="header-anchor" href="#v-процесс-пересмотра" aria-label="Permalink to &quot;V. Процесс пересмотра&quot;">​</a></h2><h3 id="_5-1-обычныи-процесс-пересмотра" tabindex="-1">5.1 Обычный процесс пересмотра <a class="header-anchor" href="#_5-1-обычныи-процесс-пересмотра" aria-label="Permalink to &quot;5.1 Обычный процесс пересмотра&quot;">​</a></h3><ol><li><strong>Подача заявки</strong> : создатель подаёт заявку на пересмотр модульному куратору, включая номер пересматриваемого документа, описание содержания пересмотра и причины пересмотра.</li><li><strong>Проверка модуля</strong> : модульный куратор проверяет содержание пересмотра, уделяя особое внимание спецификациям формата и внутримодульной согласованности. После одобрения заявка передаётся Комитету по Обслуживанию Сеттинга.</li><li><strong>Утверждение Комитета</strong> : Комитет по Обслуживанию Сеттинга проводит окончательную проверку содержания пересмотра, уделяя особое внимание межмодульной согласованности и согласованности основных настроек.</li><li><strong>Исполнение пересмотра</strong> : после утверждения модульный куратор или автор-создатель исполняет пересмотр документа.</li><li><strong>Обновление версии</strong> : после завершения пересмотра обновить номер версии документа и зафиксировать его в журнале обновлений настоящего документа.</li><li><strong>Синхронизация связанных документов</strong> : если содержание пересмотра затрагивает другие документы, связанные документы должны быть пересмотрены синхронно.</li></ol><h3 id="_5-2-срочныи-процесс-пересмотра" tabindex="-1">5.2 Срочный процесс пересмотра <a class="header-anchor" href="#_5-2-срочныи-процесс-пересмотра" aria-label="Permalink to &quot;5.2 Срочный процесс пересмотра&quot;">​</a></h3><p>Для срочных ситуаций, когда обнаружены серьёзные противоречия или ошибки сеттинга, может быть запущен срочный процесс пересмотра :</p><ol><li><strong>Срочный доклад</strong> : обнаруживший немедленно сообщает о проблеме Комитету по Обслуживанию Сеттинга.</li><li><strong>Быстрое утверждение</strong> : Комитет в течение 24 часов завершает срочное утверждение и предоставляет план пересмотра.</li><li><strong>Исполнение пересмотра</strong> : назначается ответственное лицо для немедленного исполнения пересмотра.</li><li><strong>Задняя запись</strong> : после завершения пересмотра задним числом фиксируются заявка на пересмотр и записи проверки.</li></ol><h3 id="_5-3-периодическии-всестороннии-пересмотр" tabindex="-1">5.3 Периодический всесторонний пересмотр <a class="header-anchor" href="#_5-3-периодическии-всестороннии-пересмотр" aria-label="Permalink to &quot;5.3 Периодический всесторонний пересмотр&quot;">​</a></h3><p>Комитет по Обслуживанию Сеттинга ежегодно организует всесторонний пересмотр системы документов, включая :</p><ul><li>Всестороннюю самопроверку согласованности сеттинга</li><li>Централизованную обработку отзывов пользователей</li><li>Унификацию и обновление терминологической системы</li><li>Синхронное обновление индексных документов</li><li>Единую проверку и исправление форматов документов</li></ul><h2 id="vi-журнал-обновлении" tabindex="-1">VI. Журнал обновлений <a class="header-anchor" href="#vi-журнал-обновлении" aria-label="Permalink to &quot;VI. Журнал обновлений&quot;">​</a></h2><h3 id="v1-0-первая-полная-публикация" tabindex="-1">v1.0 (Первая полная публикация) <a class="header-anchor" href="#v1-0-первая-полная-публикация" aria-label="Permalink to &quot;v1.0 (Первая полная публикация)&quot;">​</a></h3><ul><li>Завершено создание и публикация всех 100 документов</li><li>Установлена полная архитектура системы документов и спецификации формата</li><li>Завершено покрытие содержания десяти больших модулей</li><li>Установлена система приложений-индексов (словарь терминов, индекс систем, юридический индекс, хронология, реестр Десяти Тысяч Рас, личности и организации, FAQ, список самопроверки, предложения по расширению, пояснения по версиям)</li></ul><h3 id="зона-записи-последующих-обновлении-версии" tabindex="-1">Зона записи последующих обновлений версий <a class="header-anchor" href="#зона-записи-последующих-обновлении-версии" aria-label="Permalink to &quot;Зона записи последующих обновлений версий&quot;">​</a></h3><p>(Содержание последующих обновлений версий будет добавляться здесь, включая номер версии, дату публикации и краткое содержание основных обновлений)</p><h2 id="vii-спецификации-цитирования-и-перекрестных-ссылок-документов" tabindex="-1">VII. Спецификации цитирования и перекрёстных ссылок документов <a class="header-anchor" href="#vii-спецификации-цитирования-и-перекрестных-ссылок-документов" aria-label="Permalink to &quot;VII. Спецификации цитирования и перекрёстных ссылок документов&quot;">​</a></h2><h3 id="_7-1-внутренние-ссылки" tabindex="-1">7.1 Внутренние ссылки <a class="header-anchor" href="#_7-1-внутренние-ссылки" aria-label="Permalink to &quot;7.1 Внутренние ссылки&quot;">​</a></h3><p>Перекрёстные ссылки между документами используют формат «номер документа-название документа», например «см. документ 84 „Общие рамки археологических протоколов“». При ссылке следует убедиться, что цитируемый документ действительно существует и что номер и название верны.</p><h3 id="_7-2-терминологические-ссылки" tabindex="-1">7.2 Терминологические ссылки <a class="header-anchor" href="#_7-2-терминологические-ссылки" aria-label="Permalink to &quot;7.2 Терминологические ссылки&quot;">​</a></h3><p>При первом использовании основного термина можно указать ссылку на соответствующую статью документа 90 «Словарь Терминов». При последующем использовании того же термина повторная ссылка не требуется.</p><h3 id="_7-3-внешние-ссылки" tabindex="-1">7.3 Внешние ссылки <a class="header-anchor" href="#_7-3-внешние-ссылки" aria-label="Permalink to &quot;7.3 Внешние ссылки&quot;">​</a></h3><p>Если необходимо сослаться на реальные материалы или художественные произведения вне системы сеттинга, следует указать источник и чётко пояснить, что данная ссылка является справочным материалом в рамках принципа «Реальность как основа» и не означает полного принятия её содержания системой сеттинга.</p><h2 id="viii-механизмы-обеспечения-качества" tabindex="-1">VIII. Механизмы обеспечения качества <a class="header-anchor" href="#viii-механизмы-обеспечения-качества" aria-label="Permalink to &quot;VIII. Механизмы обеспечения качества&quot;">​</a></h2><h3 id="_8-1-самопроверка-противоречии-сеттинга" tabindex="-1">8.1 Самопроверка противоречий сеттинга <a class="header-anchor" href="#_8-1-самопроверка-противоречии-сеттинга" aria-label="Permalink to &quot;8.1 Самопроверка противоречий сеттинга&quot;">​</a></h3><p>Все вновь созданные и пересмотренные документы должны пройти все пункты проверки Списка Самопроверки Противоречий Сеттинга (документ 97), включая более 40 пунктов в трёх больших категориях : согласованность основных настроек, межмодульная логическая согласованность и спецификации формата документов.</p><h3 id="_8-2-перекрестная-проверка" tabindex="-1">8.2 Перекрёстная проверка <a class="header-anchor" href="#_8-2-перекрестная-проверка" aria-label="Permalink to &quot;8.2 Перекрёстная проверка&quot;">​</a></h3><p>Каждый документ перед официальной публикацией должен пройти перекрёстную проверку не менее чем одним другим создателем, с особым вниманием к межмодульной логической согласованности и терминологической унификации.</p><h3 id="_8-3-механизм-обратнои-связи-пользователеи" tabindex="-1">8.3 Механизм обратной связи пользователей <a class="header-anchor" href="#_8-3-механизм-обратнои-связи-пользователеи" aria-label="Permalink to &quot;8.3 Механизм обратной связи пользователей&quot;">​</a></h3><p>Система документов создаёт каналы обратной связи пользователей ; пользователи могут подавать отзывы следующими способами :</p><ul><li>Сообщать о противоречиях сеттинга и логических ошибках</li><li>Поднимать вопросы неединообразия терминологии</li><li>Предлагать дополнения или пересмотр конкретного содержания</li><li>Указывать на ошибки формата и текста</li></ul><p>Все отзывы классифицируются и обрабатываются модульными кураторами, а важные отзывы передаются Комитету по Обслуживанию Сеттинга на рассмотрение.</p><h3 id="_8-4-квартальныи-отчет-о-согласованности" tabindex="-1">8.4 Квартальный отчёт о согласованности <a class="header-anchor" href="#_8-4-квартальныи-отчет-о-согласованности" aria-label="Permalink to &quot;8.4 Квартальный отчёт о согласованности&quot;">​</a></h3><p>Комитет по Обслуживанию Сеттинга ежеквартально публикует «Отчёт о Согласованности Сеттинга», содержание которого включает :</p><ul><li>Обнаруженные за квартал противоречия сеттинга и их обработку</li><li>Статистику пересмотров документов за квартал</li><li>Прогресс унификации терминологии</li><li>Обработку отзывов пользователей</li><li>План обслуживания на следующий квартал</li></ul><h2 id="ix-хранение-и-распространение-документов" tabindex="-1">IX. Хранение и распространение документов <a class="header-anchor" href="#ix-хранение-и-распространение-документов" aria-label="Permalink to &quot;IX. Хранение и распространение документов&quot;">​</a></h2><h3 id="_9-1-формат-хранения" tabindex="-1">9.1 Формат хранения <a class="header-anchor" href="#_9-1-формат-хранения" aria-label="Permalink to &quot;9.1 Формат хранения&quot;">​</a></h3><p>Все документы хранятся в формате Markdown (.md), обеспечивающем кроссплатформенную читаемость и удобство управления версиями. Документы используют кодировку UTF-8, поддерживающую китайский язык и специальные символы.</p><h3 id="_9-2-структура-каталога" tabindex="-1">9.2 Структура каталога <a class="header-anchor" href="#_9-2-структура-каталога" aria-label="Permalink to &quot;9.2 Структура каталога&quot;">​</a></h3><p>Документы единообразно хранятся в каталоге <code>anchor-docs/</code>, с именами файлов в формате <code>XX-Название документа.md</code>. SPEC.md как файл спецификаций также хранится в том же каталоге.</p><h3 id="_9-3-управление-версиями" tabindex="-1">9.3 Управление версиями <a class="header-anchor" href="#_9-3-управление-версиями" aria-label="Permalink to &quot;9.3 Управление версиями&quot;">​</a></h3><p>Рекомендуется использовать системы контроля версий, такие как Git, для управления версиями документов, прикрепляя к каждой подаче пересмотра подробное commit message с фиксацией содержания и причин пересмотра.</p><h3 id="_9-4-способы-распространения" tabindex="-1">9.4 Способы распространения <a class="header-anchor" href="#_9-4-способы-распространения" aria-label="Permalink to &quot;9.4 Способы распространения&quot;">​</a></h3><p>Система документов может распространяться следующими способами :</p><ul><li>Упаковка в ZIP-архив для скачивания</li><li>Развёртывание как статический сайт для онлайн-просмотра</li><li>Конвертация в формат PDF или EPUB для чтения</li><li>Импорт в системы баз знаний для структурированного управления</li></ul><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Версия Документов и Пояснения по Обслуживанию — это «административная конституция» системы сеттинга Симбиотической Цивилизации Якоря. Она устанавливает правила версий, организацию обслуживания, процесс пересмотра, механизмы обеспечения качества и способы хранения и распространения системы документов, гарантируя, что эта обширная система сеттинга из 100 документов сможет в процессе непрерывного роста всегда сохранять порядок и согласованность. Хорошая система сеттинга требует не только превосходного содержания, но и совершенного механизма обслуживания для обеспечения её долгосрочного здорового развития. Настоящий документ является основным носителем этого механизма.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>97-设定矛盾自查表 (Список Самопроверки Противоречий Сеттинга)</li><li>90-术语词典 (Словарь Терминов)</li><li>00-衡元宙宇宙总览 (Хэн Юаньчжоу: Обзор Вселенной)</li></ul>',77)])])}const _=i(r,[["render",o]]);export{b as __pageData,_ as default};
